package main

import (
	"container/list"
	"sync"
	"time"
)

// entry holds a cached value along with metadata for LRU and TTL tracking.
type entry struct {
	key        string
	value      interface{}
	expiresAt  time.Time
	lastAccess time.Time
}

// ChunkIterator is a thread-safe LRU cache with per-entry TTL expiration.
//
// On Get, expired entries are lazily evicted. When the cache is at capacity
// and a new key is inserted, the least-recently-used entry is evicted first.
type ChunkIterator struct {
	mu       sync.RWMutex
	capacity int
	ttl      time.Duration
	items    map[string]*list.Element
	order    *list.List // front = most recent, back = least recent
}

// NewChunkIterator creates a cache with the given capacity and default TTL.
// Capacity must be > 0; TTL must be > 0.
func NewChunkIterator(capacity int, ttl time.Duration) *ChunkIterator {
	if capacity <= 0 {
		panic("chunk_iterator: capacity must be positive")
	}
	if ttl <= 0 {
		panic("chunk_iterator: ttl must be positive")
	}
	return &ChunkIterator{
		capacity: capacity,
		ttl:      ttl,
		items:    make(map[string]*list.Element, capacity),
		order:    list.New(),
	}
}

// Get retrieves a value by key. Returns (value, true) if found and not
// expired, or (nil, false) otherwise. Expired entries are evicted on access.
func (c *ChunkIterator) Get(key string) (interface{}, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	elem, ok := c.items[key]
	if !ok {
		return nil, false
	}

	e := elem.Value.(*entry)

	// Lazy TTL expiration.
	if time.Now().After(e.expiresAt) {
		c.removeElement(elem)
		return nil, false
	}

	// Promote to most-recently-used.
	e.lastAccess = time.Now()
	c.order.MoveToFront(elem)
	return e.value, true
}

// Set inserts or updates a key-value pair. If the key already exists its
// value and TTL are refreshed. When the cache exceeds capacity the
// least-recently-used entry is evicted.
func (c *ChunkIterator) Set(key string, value interface{}) {
	c.mu.Lock()
	defer c.mu.Unlock()

	// Update existing entry.
	if elem, ok := c.items[key]; ok {
		e := elem.Value.(*entry)
		e.value = value
		e.expiresAt = time.Now().Add(c.ttl)
		e.lastAccess = time.Now()
		c.order.MoveToFront(elem)
		return
	}

	// Evict LRU if at capacity.
	if c.order.Len() >= c.capacity {
		c.evictOldest()
	}

	now := time.Now()
	e := &entry{
		key:        key,
		value:      value,
		expiresAt:  now.Add(c.ttl),
		lastAccess: now,
	}
	elem := c.order.PushFront(e)
	c.items[key] = elem
}

// Delete removes a key. Returns true if the key existed.
func (c *ChunkIterator) Delete(key string) bool {
	c.mu.Lock()
	defer c.mu.Unlock()

	elem, ok := c.items[key]
	if !ok {
		return false
	}
	c.removeElement(elem)
	return true
}

// Len returns the number of non-expired entries currently in the cache.
// Expired entries are only removed lazily, so the count may include
// entries whose TTL has elapsed but which have not yet been accessed.
func (c *ChunkIterator) Len() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.order.Len()
}

// Purge removes all entries.
func (c *ChunkIterator) Purge() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.items = make(map[string]*list.Element, c.capacity)
	c.order.Init()
}

// Keys returns the keys of all non-expired entries ordered from most-recently
// to least-recently used.
func (c *ChunkIterator) Keys() []string {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now()
	keys := make([]string, 0, c.order.Len())
	for elem := c.order.Front(); elem != nil; {
		next := elem.Next()
		e := elem.Value.(*entry)
		if now.After(e.expiresAt) {
			c.removeElement(elem)
		} else {
			keys = append(keys, e.key)
		}
		elem = next
	}
	return keys
}

// removeElement deletes an element from both the list and the map.
// Caller must hold c.mu.
func (c *ChunkIterator) removeElement(elem *list.Element) {
	e := elem.Value.(*entry)
	delete(c.items, e.key)
	c.order.Remove(elem)
}

// evictOldest removes the least-recently-used entry.
// Caller must hold c.mu.
func (c *ChunkIterator) evictOldest() {
	back := c.order.Back()
	if back != nil {
		c.removeElement(back)
	}
}

package main

import (
	"fmt"
	"sync"
	"testing"
	"time"
)

func TestNewChunkIterator_PanicsOnInvalidArgs(t *testing.T) {
	t.Run("zero capacity", func(t *testing.T) {
		defer func() {
			if r := recover(); r == nil {
				t.Error("expected panic for zero capacity")
			}
		}()
		NewChunkIterator(0, time.Second)
	})
	t.Run("negative capacity", func(t *testing.T) {
		defer func() {
			if r := recover(); r == nil {
				t.Error("expected panic for negative capacity")
			}
		}()
		NewChunkIterator(-1, time.Second)
	})
	t.Run("zero TTL", func(t *testing.T) {
		defer func() {
			if r := recover(); r == nil {
				t.Error("expected panic for zero TTL")
			}
		}()
		NewChunkIterator(10, 0)
	})
	t.Run("negative TTL", func(t *testing.T) {
		defer func() {
			if r := recover(); r == nil {
				t.Error("expected panic for negative TTL")
			}
		}()
		NewChunkIterator(10, -time.Second)
	})
}

func TestSetAndGet_Basic(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)

	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("c", 3)

	for _, tc := range []struct {
		key  string
		want int
	}{
		{"a", 1},
		{"b", 2},
		{"c", 3},
	} {
		v, ok := c.Get(tc.key)
		if !ok {
			t.Errorf("Get(%q): expected found", tc.key)
		}
		if v.(int) != tc.want {
			t.Errorf("Get(%q) = %v, want %d", tc.key, v, tc.want)
		}
	}
}

func TestGet_MissingKey(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)
	v, ok := c.Get("missing")
	if ok || v != nil {
		t.Errorf("expected (nil, false) for missing key, got (%v, %v)", v, ok)
	}
}

func TestSet_OverwritesExistingKey(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)

	c.Set("a", 1)
	c.Set("a", 99)

	v, ok := c.Get("a")
	if !ok || v.(int) != 99 {
		t.Errorf("expected overwritten value 99, got %v (found=%v)", v, ok)
	}
	if c.Len() != 1 {
		t.Errorf("expected len 1 after overwrite, got %d", c.Len())
	}
}

func TestDelete(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)
	c.Set("a", 1)

	if !c.Delete("a") {
		t.Error("Delete returned false for existing key")
	}
	if c.Delete("a") {
		t.Error("Delete returned true for already-deleted key")
	}
	if _, ok := c.Get("a"); ok {
		t.Error("Get found deleted key")
	}
}

func TestPurge(t *testing.T) {
	c := NewChunkIterator(5, time.Minute)
	for i := 0; i < 5; i++ {
		c.Set(fmt.Sprintf("k%d", i), i)
	}
	c.Purge()
	if c.Len() != 0 {
		t.Errorf("expected len 0 after Purge, got %d", c.Len())
	}
	if _, ok := c.Get("k0"); ok {
		t.Error("Get found key after Purge")
	}
}

func TestLen(t *testing.T) {
	c := NewChunkIterator(5, time.Minute)
	if c.Len() != 0 {
		t.Errorf("empty cache len = %d, want 0", c.Len())
	}
	c.Set("a", 1)
	c.Set("b", 2)
	if c.Len() != 2 {
		t.Errorf("len = %d, want 2", c.Len())
	}
}

func TestLRU_Eviction(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)

	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("c", 3)
	// Cache is full: [c, b, a] (front to back)

	// Insert a 4th key — "a" (LRU) should be evicted.
	c.Set("d", 4)

	if _, ok := c.Get("a"); ok {
		t.Error("LRU key 'a' should have been evicted")
	}
	for _, k := range []string{"b", "c", "d"} {
		if _, ok := c.Get(k); !ok {
			t.Errorf("key %q should still be in cache", k)
		}
	}
}

func TestLRU_AccessPromotesEntry(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)

	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("c", 3)
	// Order: [c, b, a]

	// Access "a" to promote it to MRU.
	c.Get("a")
	// Order: [a, c, b]

	// Insert "d" — "b" (now LRU) should be evicted.
	c.Set("d", 4)

	if _, ok := c.Get("b"); ok {
		t.Error("key 'b' should have been evicted")
	}
	if _, ok := c.Get("a"); !ok {
		t.Error("key 'a' should still exist (was promoted)")
	}
}

func TestLRU_UpdatePromotesEntry(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)

	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("c", 3)
	// Order: [c, b, a]

	// Update "a" — it should be promoted.
	c.Set("a", 10)
	// Order: [a, c, b]

	// Insert "d" — "b" (LRU) should be evicted.
	c.Set("d", 4)

	if _, ok := c.Get("b"); ok {
		t.Error("key 'b' should have been evicted")
	}
	v, ok := c.Get("a")
	if !ok || v.(int) != 10 {
		t.Errorf("expected 'a'=10, got %v (found=%v)", v, ok)
	}
}

func TestTTL_Expiration(t *testing.T) {
	c := NewChunkIterator(10, 50*time.Millisecond)

	c.Set("a", 1)
	if _, ok := c.Get("a"); !ok {
		t.Fatal("key 'a' should exist immediately after Set")
	}

	time.Sleep(60 * time.Millisecond)

	if _, ok := c.Get("a"); ok {
		t.Error("key 'a' should have expired")
	}
}

func TestTTL_UpdateRefreshesTTL(t *testing.T) {
	c := NewChunkIterator(10, 50*time.Millisecond)

	c.Set("a", 1)
	time.Sleep(30 * time.Millisecond)

	// Refresh TTL.
	c.Set("a", 2)
	time.Sleep(30 * time.Millisecond)

	// Should still be alive (original TTL would have expired at 50ms).
	v, ok := c.Get("a")
	if !ok || v.(int) != 2 {
		t.Errorf("expected 'a'=2 after TTL refresh, got %v (found=%v)", v, ok)
	}
}

func TestTTL_ExpiredEntryEvictsOnGet(t *testing.T) {
	c := NewChunkIterator(3, 30*time.Millisecond)

	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("c", 3)

	time.Sleep(40 * time.Millisecond)

	// Expired entry should be lazily removed on Get.
	if _, ok := c.Get("a"); ok {
		t.Error("expired key 'a' should not be found")
	}
	if c.Len() != 2 {
		t.Errorf("len = %d after lazy eviction, want 2", c.Len())
	}
}

func TestTTL_ExpiredEntriesRemovedByKeys(t *testing.T) {
	c := NewChunkIterator(10, 30*time.Millisecond)

	c.Set("a", 1)
	c.Set("b", 2)

	time.Sleep(40 * time.Millisecond)

	keys := c.Keys()
	if len(keys) != 0 {
		t.Errorf("Keys() should have removed expired entries, got %v", keys)
	}
	if c.Len() != 0 {
		t.Errorf("Len() = %d after Keys() cleanup, want 0", c.Len())
	}
}

func TestKeys_ReturnsMRUOrder(t *testing.T) {
	c := NewChunkIterator(5, time.Minute)

	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("c", 3)
	c.Get("a") // promote "a"

	keys := c.Keys()
	expected := []string{"a", "c", "b"}
	if len(keys) != len(expected) {
		t.Fatalf("len(Keys()) = %d, want %d", len(keys), len(expected))
	}
	for i, k := range keys {
		if k != expected[i] {
			t.Errorf("Keys()[%d] = %q, want %q", i, k, expected[i])
		}
	}
}

// --- Concurrency tests ---

func TestConcurrent_ReadWrite(t *testing.T) {
	c := NewChunkIterator(100, 5*time.Second)
	const goroutines = 50
	const ops = 200

	var wg sync.WaitGroup
	wg.Add(goroutines * 2)

	// Writers.
	for g := 0; g < goroutines; g++ {
		go func(id int) {
			defer wg.Done()
			for i := 0; i < ops; i++ {
				key := fmt.Sprintf("key-%d-%d", id, i)
				c.Set(key, i)
			}
		}(g)
	}

	// Readers.
	for g := 0; g < goroutines; g++ {
		go func(id int) {
			defer wg.Done()
			for i := 0; i < ops; i++ {
				key := fmt.Sprintf("key-%d-%d", id, i)
				c.Get(key)
			}
		}(g)
	}

	wg.Wait()
}

func TestConcurrent_SetSameKey(t *testing.T) {
	c := NewChunkIterator(10, time.Minute)
	const goroutines = 100

	var wg sync.WaitGroup
	wg.Add(goroutines)

	for g := 0; g < goroutines; g++ {
		go func(id int) {
			defer wg.Done()
			c.Set("shared", id)
		}(g)
	}

	wg.Wait()

	v, ok := c.Get("shared")
	if !ok {
		t.Fatal("shared key should exist")
	}
	// Value should be one of the goroutine IDs.
	if v.(int) < 0 || v.(int) >= goroutines {
		t.Errorf("unexpected value %v", v)
	}
}

func TestConcurrent_DeleteWhileReading(t *testing.T) {
	c := NewChunkIterator(100, time.Minute)
	for i := 0; i < 100; i++ {
		c.Set(fmt.Sprintf("k%d", i), i)
	}

	const goroutines = 20
	var wg sync.WaitGroup
	wg.Add(goroutines * 2)

	// Readers.
	for g := 0; g < goroutines; g++ {
		go func() {
			defer wg.Done()
			for i := 0; i < 100; i++ {
				c.Get(fmt.Sprintf("k%d", i))
			}
		}()
	}

	// Deleters.
	for g := 0; g < goroutines; g++ {
		go func(id int) {
			defer wg.Done()
			for i := 0; i < 100; i++ {
				c.Delete(fmt.Sprintf("k%d", (id*100+i)%100))
			}
		}(g)
	}

	wg.Wait()
}

func TestConcurrent_LenWhileModifying(t *testing.T) {
	c := NewChunkIterator(50, time.Minute)
	const goroutines = 20
	var wg sync.WaitGroup
	wg.Add(goroutines * 2)

	for g := 0; g < goroutines; g++ {
		go func(id int) {
			defer wg.Done()
			for i := 0; i < 50; i++ {
				c.Set(fmt.Sprintf("k-%d-%d", id, i), i)
			}
		}(g)
	}

	for g := 0; g < goroutines; g++ {
		go func() {
			defer wg.Done()
			for i := 0; i < 50; i++ {
				_ = c.Len()
			}
		}()
	}

	wg.Wait()
}

// --- Edge-case tests ---

func TestCapacityOne(t *testing.T) {
	c := NewChunkIterator(1, time.Minute)

	c.Set("a", 1)
	if _, ok := c.Get("a"); !ok {
		t.Fatal("key 'a' should exist")
	}

	c.Set("b", 2)
	if _, ok := c.Get("a"); ok {
		t.Error("key 'a' should be evicted after inserting 'b' into capacity-1 cache")
	}
	if _, ok := c.Get("b"); !ok {
		t.Error("key 'b' should exist")
	}
}

func TestLargeCapacity(t *testing.T) {
	const n = 10000
	c := NewChunkIterator(n, time.Minute)

	for i := 0; i < n; i++ {
		c.Set(fmt.Sprintf("k%d", i), i)
	}
	if c.Len() != n {
		t.Errorf("len = %d, want %d", c.Len(), n)
	}

	// All keys should be retrievable.
	for i := 0; i < n; i++ {
		v, ok := c.Get(fmt.Sprintf("k%d", i))
		if !ok || v.(int) != i {
			t.Errorf("Get(k%d) = %v, %v", i, v, ok)
		}
	}
}

func TestNilValue(t *testing.T) {
	c := NewChunkIterator(5, time.Minute)
	c.Set("nil", nil)

	v, ok := c.Get("nil")
	if !ok {
		t.Fatal("nil-valued key should be retrievable")
	}
	if v != nil {
		t.Errorf("expected nil, got %v", v)
	}
}

func TestEmptyKey(t *testing.T) {
	c := NewChunkIterator(5, time.Minute)
	c.Set("", "empty")

	v, ok := c.Get("")
	if !ok || v.(string) != "empty" {
		t.Errorf("empty key not stored/retrieved correctly: %v, %v", v, ok)
	}
}

func TestGet_MultipleTimesDoesNotDuplicate(t *testing.T) {
	c := NewChunkIterator(5, time.Minute)
	c.Set("a", 1)
	c.Get("a")
	c.Get("a")
	if c.Len() != 1 {
		t.Errorf("len = %d after multiple Gets, want 1", c.Len())
	}
}

func TestOverwriteDoesNotGrowBeyondCapacity(t *testing.T) {
	c := NewChunkIterator(3, time.Minute)

	for i := 0; i < 100; i++ {
		c.Set("same", i)
	}
	if c.Len() != 1 {
		t.Errorf("len = %d after 100 overwrites of same key, want 1", c.Len())
	}
}

func TestEvictionUnderTTLPressure(t *testing.T) {
	c := NewChunkIterator(3, 40*time.Millisecond)

	c.Set("a", 1)
	c.Set("b", 2)
	c.Set("c", 3)

	// Let all entries expire.
	time.Sleep(50 * time.Millisecond)

	// Insert new entries — expired ones are still in the map until accessed,
	// but capacity eviction should still work correctly.
	c.Set("d", 4)
	c.Set("e", 5)
	c.Set("f", 6)

	// Old expired keys should not be retrievable.
	for _, k := range []string{"a", "b", "c"} {
		if _, ok := c.Get(k); ok {
			t.Errorf("expired key %q should not be retrievable", k)
		}
	}

	// New keys should be retrievable.
	for _, k := range []string{"d", "e", "f"} {
		if _, ok := c.Get(k); !ok {
			t.Errorf("new key %q should be retrievable", k)
		}
	}
}

func BenchmarkChunkIterator_Set(b *testing.B) {
	c := NewChunkIterator(1000, time.Minute)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		c.Set(fmt.Sprintf("k%d", i%1000), i)
	}
}

func BenchmarkChunkIterator_Get_Hit(b *testing.B) {
	c := NewChunkIterator(1000, time.Minute)
	for i := 0; i < 1000; i++ {
		c.Set(fmt.Sprintf("k%d", i), i)
	}
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		c.Get(fmt.Sprintf("k%d", i%1000))
	}
}

func BenchmarkChunkIterator_Get_Miss(b *testing.B) {
	c := NewChunkIterator(1000, time.Minute)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		c.Get("missing")
	}
}

func BenchmarkChunkIterator_SetGet_Parallel(b *testing.B) {
	c := NewChunkIterator(1000, time.Minute)
	b.RunParallel(func(pb *testing.PB) {
		i := 0
		for pb.Next() {
			key := fmt.Sprintf("k%d", i%1000)
			c.Set(key, i)
			c.Get(key)
			i++
		}
	})
}
